  "question": "Does periodic driving increase RMS displacement against an otherwise matched damped oscillator?",
  "hypothesis": "Under conditions where the driving force amplitude (F_0) is small relative to the inherent damping forces, or when the driving frequency ($\\Omega$) is significantly detuned from the natural frequency ($\\omega_0$), the Root Mean Square (RMS) displacement of the driven system will be statistically indistinguishable from the undriven reference oscillator.",
  "competing_hypothesis": "Periodic driving always increases RMS displacement, even when far from resonance or for small forcing amplitudes.",
  "parameters": {
    "mass": {"value": 1.0, "unit": "kg"},
    "damping": {"value": 0.5, "unit": "kg/s"},
    "stiffness": {"value": 10.0, "unit": "N/m"},
