  },
  "analysis": {
    "method": "matched_rms_displacement",
    "expected_direction": "increase",
    "minimum_effect_m": 1e-6,
    "max_reference_error_m": 1e-6,
    "max_reference_velocity_error_m_per_s": 1e-6
  },
  "budget": {
    "max_steps": 500,
